INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 19, 'theory', 'Quiz: indexes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 0, 'There is a composite index on (city, created). Which query can use it efficiently?', '["WHERE city = ''Moscow'' AND created >= ''2024-02-01''", "WHERE created = ''2024-02-01''", "WHERE city LIKE ''%cow''", "WHERE lower(city) = ''moscow''"]', 0, 'The left prefix works: equality on city first, then a range on created. A query on created alone, a leading %, and a function over the column do not use the index.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 1, 'Why does a B-tree with a billion keys stay very shallow?', '["Because the keys are compressed", "Because the whole tree is kept in RAM", "Because a page holds hundreds of keys — the fan-out is large, and 3–4 levels are enough", "Because the tree is rebuilt on every read"]', 2, 'Depth is roughly a logarithm to the base of the fan-out: with 300 children per node, three levels give tens of millions of rows, four give billions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 2, 'What does "COVERING INDEX" mean in a query plan?', '["The index covers the whole table and is therefore expensive", "All the columns the query needs are in the index, and there is no need to look in the table", "The index was created automatically", "The query uses neither indexes nor the table"]', 1, 'A covering index saves reading the table (index-only scan), but it is wider and costlier to update: create it for the hottest queries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 3, 'What is wrong with paginating through OFFSET 100000?', '["Nothing, the database simply jumps to the right row", "OFFSET is forbidden in SQL", "OFFSET turns off sorting", "The database reads and discards all the previous rows, so deep pages become slow"]', 3, 'Keyset pagination remembers the last key and uses the condition "after it" — the index costs the same on any page.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 19, 4, 'Why not simply create an index on every column "just in case"?', '["Indexes are forbidden on tables with foreign keys", "Only one index per table works", "Every index slows down inserts and updates and takes up space, and many will never be used", "Because of indexes, queries return wrong data"]', 2, 'Write amplification: changing a row updates all of its indexes. Create an index for a specific frequent query, and periodically clean out unused and duplicate ones.');
